-- Eliminar tabla previa si existe
DROP TABLE IF EXISTS saber11_sucre;

-- Definición del esquema DDL
CREATE TABLE saber11_sucre (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    periodo INTEGER NOT NULL,
    estu_genero VARCHAR(10) NOT NULL,
    estu_mcpio_reside VARCHAR(100) NOT NULL,
    fami_estratovivienda VARCHAR(50) NOT NULL,
    fami_personashogar VARCHAR(20),
    fami_tieneinternet VARCHAR(10),
    fami_tienecomputador VARCHAR(10),
    cole_naturaleza VARCHAR(50) NOT NULL,
    cole_jornada VARCHAR(50) NOT NULL,
    punt_lectura_critica INTEGER NOT NULL,
    punt_matematicas INTEGER NOT NULL,
    punt_c_naturales INTEGER NOT NULL,
    punt_sociales_ciudadanas INTEGER NOT NULL,
    punt_ingles INTEGER NOT NULL,
    punt_global INTEGER NOT NULL
);

-- Creación de índices optimizados para consultas y analítica
CREATE INDEX idx_saber11_mcpio ON saber11_sucre(estu_mcpio_reside);
CREATE INDEX idx_saber11_estrato ON saber11_sucre(fami_estratovivienda);
CREATE INDEX idx_saber11_naturaleza ON saber11_sucre(cole_naturaleza);
CREATE INDEX idx_saber11_genero ON saber11_sucre(estu_genero);
CREATE INDEX idx_saber11_punt_global ON saber11_sucre(punt_global);

-- Inserción masiva de los 1,452 registros reales
